// CSD_RATIONALE_BEGIN
// Two primary failure modes to fix:
//
// 1. 25/49 examples never emitted "<<" (no constrained activity).
//    Cause (attempt 27): single loop had no forced span after preamble exhaustion.
//    Cause (best attempt): Phase 4 used forbidden `next == "<<"` exact-equality
//    check instead of `RenderedEndsWith`, missing split-token delimiters.
//    Fix: detect "<<" in Phase 1 with `RenderedEndsWith`, then forcibly
//    OpenConstrainedSpan if preamble ends without one.
//
// 2. 21/49 examples had valid spans but tiny content (avg 1.57 tokens, wrong answer).
//    Cause: Phase 2 called `CloseSpanIfComplete` eagerly after every ConstrainedStep.
//    For arithmetic expression parsers, a lone variable like "n" is a complete parse,
//    so the span closed after 1 token even though "n - int(n*frac)" was the real answer.
//    Fix: Replace the eager-close inner loop with `CloseSpanWithinBudget`, which
//    generates forward, tracks the LONGEST complete prefix reached, and closes
//    at that last complete point — yielding the full multi-term expression.
//
// Strategy outline:
//   Phase 1: UnconstrainedStep loop (up to 600 tokens), watching for naturally
//            emitted "<<" via RenderedEndsWith. If detected, enter constrained mode.
//   Phase 2: If Phase 1 ends without an open span, force OpenConstrainedSpan.
//   Phase 3: Call CloseSpanWithinBudget with all remaining budget on the open span.
//            This drives the model to emit the full arithmetic expression and closes
//            at the last parser-complete prefix found within budget.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedStep loop):
//     While outside a span, the invariant holds vacuously (insideConstrainedOut=false).
//     When RenderedEndsWith fires, EnterObservedConstrainedSpan sets
//     currentConstrainedOut := [], and parser.IsValidPrefix([]) holds by the method
//     precondition. So validity is preserved at every step.
//
//   Phase 2 (OpenConstrainedSpan):
//     This helper sets insideConstrainedOut := true and currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by precondition. Invariant preserved.
//
//   Phase 3 (CloseSpanWithinBudget):
//     The postcondition of CloseSpanWithinBudget directly states
//     `insideOut ==> parser.IsValidPrefix(currentOut)`, preserving the invariant.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
//   Phase 1:
//     Each iteration: UnconstrainedStep adds exactly 1 to steps and at most 1 to
//     generated (EOS is not appended). EnterObservedConstrainedSpan is +0 to both.
//     So |generated| - |generatedPrefix| <= steps after every iteration.
//
//   Phase 2:
//     OpenConstrainedSpan appends "<<" (1 token visible growth) and steps := steps+1.
//     Bound preserved: |generated|+1 <= |generatedPrefix|+steps+1 = |generatedPrefix|+new_steps.
//
//   Phase 3:
//     closeBudget = maxSteps - steps. CloseSpanWithinBudget postcondition gives
//     |generatedOut| <= |generated| + closeBudget. After step update:
//     |generatedOut| <= |generatedPrefix| + steps_old + closeBudget
//                    = |generatedPrefix| + maxSteps = |generatedPrefix| + steps_new. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve step by step. At the very end write: The answer is <<EXPR>> where EXPR is the arithmetic formula using variable names from the problem and operators +,-,*,/,(). No LaTeX, no backslashes, no dollar signs. Example: The answer is <<n * p * (1 + r/100)>>");

var steps: nat := 0;

var preambleBudget: nat := 600;
if preambleBudget > maxSteps {
  preambleBudget := maxSteps;
}

// Phase 1: Free reasoning, detecting "<<" via RenderedEndsWith
while steps < preambleBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases preambleBudget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
  }
}

// Phase 2: Force open a constrained span if none was detected
if !insideConstrainedOut && steps < maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg;
  insideConstrainedOut := fi;
  currentConstrainedOut := fc;
  steps := steps + 1;
}

// Phase 3: Generate the full arithmetic expression and close the span
if insideConstrainedOut && steps < maxSteps {
  var closeBudget: nat := maxSteps - steps;
  var wg, wi, wc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := wg;
  insideConstrainedOut := wi;
  currentConstrainedOut := wc;
  steps := steps + closeBudget;
}

cost := steps;

